-- Official client downloads only. This does not attest client-generated bytes.
begin;
set local lock_timeout='5s';
create schema bank_security;
revoke all on schema bank_security from public,anon,authenticated;
create table bank_security.settings(space_id uuid primary key references public.bank_spaces(id),enabled boolean not null default false,threshold numeric(5,2) not null default 90 check(threshold>0 and threshold<=100),version bigint not null default 0);
create table bank_security.identities(space_id uuid not null,user_id uuid not null,identifier text not null check(identifier ~ '^[0-9]{4,12}$'),created_at timestamptz not null default now(),primary key(space_id,user_id),unique(space_id,identifier));
-- No FK to auth.users: identity and evidence survive account deletion.
create table bank_security.accounts(space_id uuid not null,user_id uuid not null,blocked boolean not null default false,blocked_at timestamptz,reason text,allow_until_count integer not null default 0,primary key(space_id,user_id));
create table bank_security.downloads(id uuid primary key,space_id uuid not null,user_id uuid not null,format text not null check(format in ('pdf','docx','hwpx','backup')),kind text not null check(kind in ('question','exam','mock','backup','local')),exam_id uuid,revision_ids uuid[] not null,question_ids uuid[] not null,source_ids text[] not null,requested_at timestamptz not null default now(),finished_at timestamptz,state text not null default 'requested' check(state in ('requested','authorized','failed','blocked')),reason text,unique(space_id,user_id,id));
create index downloads_user_time on bank_security.downloads(space_id,user_id,requested_at desc,id);
create table bank_security.issued_sources(space_id uuid not null,user_id uuid not null,source_id text not null,first_request uuid not null references bank_security.downloads(id),primary key(space_id,user_id,source_id));
create table bank_security.events(id bigint generated always as identity primary key,space_id uuid not null,user_id uuid,actor_id uuid,event text not null,details jsonb not null default '{}',created_at timestamptz not null default now());
create table bank_security.install_backup(name text primary key,value text not null);
insert into bank_security.install_backup values('bank_member',pg_get_functiondef('public.bank_member(uuid,boolean)'::regprocedure));
insert into bank_security.settings(space_id) select id from public.bank_spaces;
do $$ declare t text;begin foreach t in array array['settings','identities','accounts','downloads','issued_sources','events','install_backup'] loop
 execute format('alter table bank_security.%I enable row level security',t);
 execute format('revoke all on bank_security.%I from public,anon,authenticated',t);
end loop;end $$;

create function bank_security.allowed(s uuid,u uuid) returns boolean language sql stable security definer set search_path='' as $$
 select not exists(select 1 from bank_security.accounts a where a.space_id=s and a.user_id=u and a.blocked)
 or exists(select 1 from bank_access.owners where space_id=s and user_id=u);
$$;
create or replace function public.bank_member(s uuid,admin boolean default false) returns boolean language sql stable security definer set search_path='' as $$
 select bank_security.allowed(s,auth.uid()) and exists(select 1 from public.bank_members m join auth.users u on u.id=auth.uid()
 where m.space_id=s and m.enabled and m.email=lower(u.email) and u.email_confirmed_at is not null
 and (m.user_id=u.id or (m.user_id is null and m.role='teacher'))
 and (m.role<>'owner' or exists(select 1 from bank_access.owners o where o.space_id=s and o.user_id=u.id))
 and (not admin or (m.role='owner' and exists(select 1 from bank_access.owners o where o.space_id=s and o.user_id=u.id))));
$$;
create function public.bank_security_session_allowed() returns boolean language sql stable security definer set search_path='' as $$
 select not exists(select 1 from bank_security.accounts a where a.user_id=auth.uid() and not bank_security.allowed(a.space_id,a.user_id));
$$;
-- Protect old definer RPCs too, without changing their contracts. Storage and
-- Realtime remain covered by RLS / bank_member, not by this PostgREST hook alone.
create function public.bank_security_request_guard() returns void language plpgsql security definer set search_path='' as $$
 begin if not public.bank_security_session_allowed() then raise exception '이용이 제한되었습니다. 서비스 운영자에게 문의하세요.' using errcode='42501';end if;end $$;
do $$ declare previous text;t record;begin
 select split_part(v,'=',2) into previous from pg_roles r cross join lateral unnest(r.rolconfig) v where r.rolname='authenticator' and v like 'pgrst.db_pre_request=%';
 if coalesce(previous,'')<>'' then raise exception 'Existing pre-request hook requires explicit integration';end if;
 insert into bank_security.install_backup values('pre_request',coalesce(previous,''));
 for t in select c.relname from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relkind='r' and c.relname like 'bank_%' and c.relrowsecurity loop
  execute format('create policy bank_security_session on public.%I as restrictive for all to authenticated using(public.bank_security_session_allowed()) with check(public.bank_security_session_allowed())',t.relname);
 end loop;
end $$;
alter role authenticator set pgrst.db_pre_request='public.bank_security_request_guard';

create function bank_security.sources(s uuid) returns table(source_id text) language sql stable security definer set search_path='' as $$
 with current_rows as (select distinct on(c.question_id) c.*,r.visibility from public.bank_catalog c join public.bank_revisions r on r.id=c.revision_id join public.bank_questions q on q.id=c.question_id where c.space_id=s and r.committed and not q.archived order by c.question_id,c.created_at desc,c.revision_id desc)
 select distinct c.metadata#>>'{source,documentId}' from current_rows c where c.visibility in ('approved','shared_pending')
 and c.metadata#>>'{source,kind}'='학교기출' and nullif(c.metadata#>>'{source,documentId}','') is not null
 and coalesce(c.metadata#>>'{relations,originalQuestionId}','')='';
$$;
create function bank_security.watermark(s uuid,u uuid) returns text language plpgsql security definer set search_path='' as $$
 declare code text;digits int:=4;tries int:=0;begin
 select identifier into code from bank_security.identities where space_id=s and user_id=u;if found then return code;end if;
 loop
  tries:=tries+1;if tries>100 then digits:=digits+1;tries:=0;end if;if digits>12 then raise exception 'Identifier capacity';end if;
  code:=lpad((('x'||substr(replace(gen_random_uuid()::text,'-',''),1,12))::bit(48)::bigint % power(10,digits)::bigint)::text,digits,'0');
  begin insert into bank_security.identities values(s,u,code,now());return code;exception when unique_violation then
   select identifier into code from bank_security.identities where space_id=s and user_id=u;if found then return code;end if;
  end;
 end loop;
end $$;

create function public.bank_download_begin(s uuid,request_id uuid,fmt text,revisions uuid[],request_kind text default 'exam',paper_id uuid default null) returns jsonb language plpgsql security definer set search_path='' as $$
 declare old bank_security.downloads;ids uuid[];questions uuid[];sources text[];code text;begin
 if not public.bank_member(s) then raise insufficient_privilege;end if;
 if not exists(select 1 from bank_security.settings where space_id=s) then raise exception '다운로드 설정을 확인할 수 없습니다.';end if;
 if fmt is null or request_kind is null or request_id is null or array_position(revisions,null) is not null or fmt not in ('pdf','docx','hwpx','backup') or request_kind not in ('question','exam','mock','backup','local') or cardinality(revisions)>(case when fmt='backup' and public.bank_member(s,true) then 100000 else 1000 end) or revisions is null then raise exception '다운로드 요청을 확인하세요.';end if;
 select coalesce(array_agg(distinct x order by x),'{}') into ids from unnest(revisions) x where x is not null;
 if cardinality(ids)=0 and request_kind<>'local' then raise exception '출력 문항이 없습니다.';end if;
 if exists(select 1 from unnest(ids) id where not exists(select 1 from public.bank_catalog c where c.space_id=s and c.revision_id=id and public.bank_read_revision(id))) then raise insufficient_privilege;end if;
 if paper_id is not null and not exists(select 1 from public.bank_exam_drafts where id=paper_id and space_id=s and owner_id=auth.uid()) and not exists(select 1 from public.bank_mock_exams where id=paper_id and space_id=s and owner_id=auth.uid()) then raise insufficient_privilege;end if;
 perform 1 from public.bank_spaces where id=s for share;
 if not public.bank_member(s) then raise insufficient_privilege;end if;
 insert into bank_security.accounts(space_id,user_id) values(s,auth.uid()) on conflict do nothing;
 perform 1 from bank_security.accounts where space_id=s and user_id=auth.uid() for update;
 if not bank_security.allowed(s,auth.uid()) then raise insufficient_privilege;end if;
 select * into old from bank_security.downloads where id=request_id;
 if found then
  if old.space_id<>s or old.user_id<>auth.uid() or old.format<>fmt or old.revision_ids<>ids or old.kind<>request_kind or old.exam_id is distinct from paper_id then raise insufficient_privilege;end if;
  if old.state<>'requested' then raise exception '새 다운로드 요청으로 다시 시도하세요.';end if;
 else
  select coalesce(array_agg(distinct c.metadata#>>'{source,documentId}'),'{}') into sources from public.bank_catalog c join bank_security.sources(s) source on source.source_id=c.metadata#>>'{source,documentId}' where c.revision_id=any(ids);
  select array_agg(distinct question_id order by question_id) into questions from public.bank_catalog where revision_id=any(ids);
  insert into bank_security.downloads(id,space_id,user_id,format,kind,exam_id,revision_ids,question_ids,source_ids) values(request_id,s,auth.uid(),fmt,request_kind,paper_id,ids,coalesce(questions,'{}'),sources);
 end if;
 code:=bank_security.watermark(s,auth.uid());
 return jsonb_build_object('requestId',request_id,'identifier',code);
end $$;

create function public.bank_download_finish(s uuid,request_id uuid,generated boolean) returns jsonb language plpgsql security definer set search_path='' as $$
 declare job bank_security.downloads;policy bank_security.settings;account bank_security.accounts;total int;projected int;current_sources text[];begin
 if not public.bank_member(s) then raise insufficient_privilege;end if;
 perform 1 from public.bank_spaces where id=s for share;
 if not public.bank_member(s) then raise insufficient_privilege;end if;
 select * into policy from bank_security.settings where space_id=s for share;
 if not found then raise exception '다운로드 설정을 확인할 수 없습니다.';end if;
 select * into account from bank_security.accounts where space_id=s and user_id=auth.uid() for update;
 select * into job from bank_security.downloads where id=request_id and space_id=s and user_id=auth.uid() for update;
 if not found then raise insufficient_privilege;end if;
 if not bank_security.allowed(s,auth.uid()) then return jsonb_build_object('allowed',false,'message','이용이 제한되었습니다. 서비스 운영자에게 문의하세요.');end if;
 if job.state='authorized' then return jsonb_build_object('allowed',true,'state','authorized');end if;
 if job.state<>'requested' then return jsonb_build_object('allowed',false,'message','새 다운로드 요청으로 다시 시도하세요.');end if;
 if not generated or generated is null or job.requested_at<now()-interval '2 hours' then
  update bank_security.downloads set state='failed',finished_at=now(),reason='client_generation_failed_or_expired' where id=request_id;
  return jsonb_build_object('allowed',false,'state','failed');end if;
 if exists(select 1 from unnest(job.revision_ids) id where not public.bank_read_revision(id)) then raise insufficient_privilege;end if;
 select coalesce(array_agg(source_id),'{}') into current_sources from bank_security.sources(s);total:=cardinality(current_sources);
 select count(*) into projected from unnest(current_sources) source(source_id) where source.source_id=any(job.source_ids) or exists(select 1 from bank_security.issued_sources i where i.space_id=s and i.user_id=auth.uid() and i.source_id=source.source_id);
 if policy.enabled and not public.bank_member(s,true) and total>0 and projected*100>=policy.threshold*total and projected>account.allow_until_count then
  update bank_security.accounts set blocked=true,blocked_at=now(),reason='threshold' where space_id=s and user_id=auth.uid();
  update bank_security.downloads set state='blocked',finished_at=now(),reason='threshold' where id=request_id;
  insert into bank_security.events(space_id,user_id,event,details) values(s,auth.uid(),'auto_block',jsonb_build_object('requestId',request_id,'projected',projected,'total',total,'threshold',policy.threshold));
  return jsonb_build_object('allowed',false,'message','이용이 제한되었습니다. 서비스 운영자에게 문의하세요.');
 end if;
 insert into bank_security.issued_sources select s,auth.uid(),x,request_id from unnest(job.source_ids) x on conflict do nothing;
 update bank_security.downloads set state='authorized',finished_at=now() where id=request_id;
 return jsonb_build_object('allowed',true,'state','authorized');
end $$;

create function public.bank_security_overview(s uuid,start_at int default 0,target_user uuid default null,from_at timestamptz default null,to_at timestamptz default null,revision uuid default null,watermark_code text default null) returns jsonb language plpgsql stable security definer set search_path='' as $$
 begin
 if not public.bank_member(s,true) then raise insufficient_privilege;end if;
 if start_at<0 or start_at>100000 then raise exception 'Invalid page';end if;
 return jsonb_build_object('settings',(select to_jsonb(c) from bank_security.settings c where space_id=s),'sourceTotal',(select count(*) from bank_security.sources(s)),
 'users',(select coalesce(jsonb_agg(jsonb_build_object('userId',i.user_id,'email',u.email,'identifier',i.identifier,'blocked',coalesce(a.blocked,false),'blockedAt',a.blocked_at,'allowUntilCount',a.allow_until_count,'downloads',(select count(*) from bank_security.downloads d where d.space_id=s and d.user_id=i.user_id and d.state='authorized'),'sources',(select count(*) from bank_security.issued_sources x join bank_security.sources(s) d on d.source_id=x.source_id where x.space_id=s and x.user_id=i.user_id)) order by i.created_at desc),'[]') from bank_security.identities i left join auth.users u on u.id=i.user_id left join bank_security.accounts a on a.space_id=s and a.user_id=i.user_id where i.space_id=s and (watermark_code is null or i.identifier=watermark_code)),
 'downloads',(select coalesce(jsonb_agg(to_jsonb(d)),'[]') from(select d.* from bank_security.downloads d where d.space_id=s and (watermark_code is null or exists(select 1 from bank_security.identities i where i.space_id=s and i.user_id=d.user_id and i.identifier=watermark_code)) and (target_user is null or d.user_id=target_user) and (from_at is null or d.requested_at>=from_at) and (to_at is null or d.requested_at<to_at) and (revision is null or revision=any(d.revision_ids)) order by d.requested_at desc,d.id limit 50 offset start_at) d),
 'events',(select coalesce(jsonb_agg(to_jsonb(e)),'[]') from(select * from bank_security.events where space_id=s and (target_user is null or user_id=target_user) order by created_at desc,id desc limit 50) e));
 end $$;
create function public.bank_security_configure(s uuid,threshold_percent numeric,active boolean,expected bigint) returns void language plpgsql security definer set search_path='' as $$
 begin
 if not public.bank_member(s,true) then raise insufficient_privilege;end if;
 if threshold_percent is null or active is null or threshold_percent<=0 or threshold_percent>100 then raise exception '임계값은 0 초과 100 이하입니다.';end if;
 update bank_security.settings set threshold=threshold_percent,enabled=active,version=version+1 where space_id=s and version=expected;
 if not found then raise exception '설정이 변경되었습니다. 다시 조회하세요.' using errcode='PT409';end if;
 insert into bank_security.events(space_id,actor_id,event,details) values(s,auth.uid(),'configure',jsonb_build_object('threshold',threshold_percent,'enabled',active));
 end $$;
create function public.bank_security_unblock(s uuid,target_user uuid,extra_sources int,reason_text text) returns void language plpgsql security definer set search_path='' as $$
 declare current_count int;begin
 if not public.bank_member(s,true) then raise insufficient_privilege;end if;
 if extra_sources is null or extra_sources<1 or extra_sources>10000 or reason_text is null or length(trim(reason_text)) not between 1 and 500 then raise exception '해제 사유와 추가 허용 시험지 수를 입력하세요.';end if;
 perform 1 from bank_security.accounts where space_id=s and user_id=target_user for update;
 select count(*) into current_count from bank_security.issued_sources i join bank_security.sources(s) x on x.source_id=i.source_id where i.space_id=s and i.user_id=target_user;
 update bank_security.accounts set blocked=false,allow_until_count=current_count+extra_sources where space_id=s and user_id=target_user;
 if not found then raise exception '대상을 다시 확인하세요.';end if;
 insert into bank_security.events(space_id,user_id,actor_id,event,details) values(s,target_user,auth.uid(),'unblock',jsonb_build_object('reason',reason_text,'allowUntilCount',current_count+extra_sources));
 end $$;
revoke all on all functions in schema bank_security from public,anon,authenticated;
revoke all on function public.bank_download_begin(uuid,uuid,text,uuid[],text,uuid),public.bank_download_finish(uuid,uuid,boolean),public.bank_security_overview(uuid,int,uuid,timestamptz,timestamptz,uuid,text),public.bank_security_configure(uuid,numeric,boolean,bigint),public.bank_security_unblock(uuid,uuid,int,text) from public,anon,authenticated;
grant execute on function public.bank_download_begin(uuid,uuid,text,uuid[],text,uuid),public.bank_download_finish(uuid,uuid,boolean),public.bank_security_overview(uuid,int,uuid,timestamptz,timestamptz,uuid,text),public.bank_security_configure(uuid,numeric,boolean,bigint),public.bank_security_unblock(uuid,uuid,int,text) to authenticated;
revoke all on function public.bank_security_session_allowed(),public.bank_security_request_guard() from public,anon,authenticated;
grant execute on function public.bank_security_session_allowed(),public.bank_security_request_guard() to authenticated,anon;
notify pgrst,'reload config';
notify pgrst,'reload schema';
commit;
